import * as AasXmlization from "../src/xmlization";
import * as AasTypes from "../src/types";

import * as TestCommonXmlization from "./commonXmlization";

test("Color XML round-trip OK", () => {
  const instance = TestCommonXmlization.loadMaximalBox();

  const xmlText = AasXmlization.toXmlString(instance);
  const anotherOrError = AasXmlization.fromXmlString(xmlText);
  expect(anotherOrError.error).toBeNull();

  const casted = AasTypes.asBox(anotherOrError.mustValue());
  expect(casted).not.toBeNull();
  expect(casted.color).toStrictEqual(
    instance.color
  );
});

test("Color XML deserializes Red OK", () => {
  const instance = TestCommonXmlization.loadMaximalBox();
  const xmlText = AasXmlization.toXmlString(instance);

  const regex = new RegExp(
    `(<${"color"}>)([^<]*)(</${"color"}>)`
  );
  const adaptedXmlText = xmlText.replace(
    regex,
    `$1${"Red"}$3`
  );

  const anotherOrError = AasXmlization.fromXmlString(adaptedXmlText);
  expect(anotherOrError.error).toBeNull();

  const casted = AasTypes.asBox(anotherOrError.mustValue());
  expect(casted).not.toBeNull();
  expect(casted.color).toStrictEqual(
    AasTypes.Color.Red
  );
});

